// src/components/nav.tsx
import React, { useEffect, useMemo, useState } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../components/AppLink";

import { FiMenu, FiX, FiChevronDown } from "react-icons/fi";
import { FaArrowUp } from "react-icons/fa";

interface NavProps {
  data?: {
    menu?: string[];
    whatsapp?: string;
  };
}

type ServiceLink = {
  labelKey: string; // i18n key
  to: string; // localized by Link
};

const Navigation: React.FC<NavProps> = ({ data }) => {
  const { t } = useTranslation();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showBackToTop, setShowBackToTop] = useState(false);

  // Desktop dropdown open/close + Mobile accordion open/close
  const [servicesOpenDesktop, setServicesOpenDesktop] = useState(false);
  const [servicesOpenMobile, setServicesOpenMobile] = useState(false);

  const servicesLinks: ServiceLink[] = useMemo(
    () => [
      {
        labelKey: "menu.services.webDesignDevelopment.nav",
        to: "/services/web-design-development/",
      },
      { labelKey: "menu.services.seo.nav", to: "/services/seo/" },
      {
        labelKey: "menu.services.maintenance.nav",
        to: "/services/maintenance/",
      },
      { labelKey: "menu.services.analytics.nav", to: "/services/analytics/" },
      // Optional:
      { labelKey: "menu.servicesHub.subnav", to: "/services/" },
    ],
    []
  );

  const toggleMenu = () => {
    setIsMenuOpen((v) => !v);
    // reset mobile accordion when closing
    if (isMenuOpen) setServicesOpenMobile(false);
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: "smooth" });

  useEffect(() => {
    const handleScroll = () => setShowBackToTop(window.scrollY > 100);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Close dropdown when clicking outside (desktop)
  useEffect(() => {
    const onDocClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;
      if (target.closest?.("[data-services-dropdown]")) return;
      setServicesOpenDesktop(false);
    };
    document.addEventListener("click", onDocClick);
    return () => document.removeEventListener("click", onDocClick);
  }, []);

  const ctaHref = data?.whatsapp || "mailto:juanpablo@riano.ca";
  const ctaLabel = t("menu.nav.cta"); // "Book a call" / "Réserver un appel" / "Agendar una llamada"

  return (
    <nav className={styles.container} aria-label="Primary navigation">
      {/* MOBILE burger */}
      <button
        onClick={toggleMenu}
        className={styles.burgerButton}
        aria-label="Menu"
      >
        {isMenuOpen ? (
          <FiX className="text-white fixed right-4 z-[70] top-4" size={36} />
        ) : (
          <FiMenu className="text-white text-orange mx-8" size={36} />
        )}
      </button>

      {/* DESKTOP NAV */}
      <div className={styles.desktopWrapper}>
        <ul className={styles.desktopList}>
          <li className={styles.item}>
            <Link to="/" className={styles.link}>
              {t("menu.home")}
            </Link>
          </li>

          {/* Services dropdown */}
          <li className={`${styles.item} relative`} data-services-dropdown>
            <button
              className={styles.dropdownButton}
              onClick={() => setServicesOpenDesktop((v) => !v)}
              aria-haspopup="menu"
              aria-expanded={servicesOpenDesktop}
            >
              {t("menu.servicesHub.nav")}
              <FiChevronDown className="ml-2" />
            </button>

            {servicesOpenDesktop ? (
              <div
                className={styles.dropdownPanel}
                role="menu"
                aria-label={t("menu.services") || "Services"}
              >
                <ul className="flex flex-col gap-1">
                  {/* First 4 = direct services */}
                  {servicesLinks.slice(0, 4).map((s) => (
                    <li key={s.to}>
                      <Link
                        to={s.to}
                        className={styles.dropdownLink}
                        onClick={() => setServicesOpenDesktop(false)}
                      >
                        {t(s.labelKey)}
                      </Link>
                    </li>
                  ))}
                  {/* Optional "All services" */}
                  <li className="mt-2 pt-2 border-t border-black/10">
                    <Link
                      to={servicesLinks[4].to}
                      className={styles.dropdownLinkMuted}
                      onClick={() => setServicesOpenDesktop(false)}
                    >
                      {t(servicesLinks[4].labelKey)}
                    </Link>
                  </li>
                </ul>
              </div>
            ) : null}
          </li>

          <li className={styles.item}>
            <Link to="/contractors/" className={styles.link}>
              {t("menu.contractors")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link to="/portfolio" className={styles.link}>
              {t("menu.portfolio")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link to="/about/" className={styles.link}>
              {t("menu.about")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link to="/contact/" className={styles.link}>
              {t("menu.contact")}
            </Link>
          </li>

          <li className={styles.item}>
            <Link to="/blog" className={styles.link}>
              {t("menu.blog")}
            </Link>
          </li>
        </ul>

        <a
          href={ctaHref}
          target={ctaHref.startsWith("http") ? "_blank" : undefined}
          rel={ctaHref.startsWith("http") ? "noreferrer" : undefined}
          className={styles.ctaButton}
        >
          {ctaLabel}
        </a>
      </div>

      {/* MOBILE MENU PANEL */}
      <div
        className={`${styles.mobilePanel} ${
          isMenuOpen ? styles.menuOpen : styles.menuClosed
        }`}
        aria-hidden={!isMenuOpen}
      >
        <ul className="flex flex-col items-center gap-4">
          <li>
            <Link
              to="/"
              className={styles.mobileLink}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {t("menu.home")}
            </Link>
          </li>

          {/* Mobile Services accordion */}
          <li className="w-full max-w-md">
            <button
              className={styles.mobileAccordionButton}
              onClick={() => setServicesOpenMobile((v) => !v)}
              aria-expanded={servicesOpenMobile}
            >
              <span>{t("menu.servicesHub.subnav")}</span>
              <FiChevronDown
                className={`${
                  servicesOpenMobile ? "rotate-180" : ""
                } transition-transform`}
              />
            </button>

            {servicesOpenMobile ? (
              <div className={styles.mobileAccordionPanel}>
                <ul className="flex flex-col gap-2">
                  {servicesLinks.slice(0, 4).map((s) => (
                    <li key={s.to}>
                      <Link
                        to={s.to}
                        className={styles.mobileSubLink}
                        onClick={() => {
                          setIsMenuOpen(false);
                          setServicesOpenMobile(false);
                        }}
                      >
                        {t(s.labelKey)}
                      </Link>
                    </li>
                  ))}
                  <li className="pt-2 mt-2 border-t border-white/15">
                    <Link
                      to={servicesLinks[4].to}
                      className={styles.mobileSubLinkMuted}
                      onClick={() => {
                        setIsMenuOpen(false);
                        setServicesOpenMobile(false);
                      }}
                    >
                      {t(servicesLinks[4].labelKey)}
                    </Link>
                  </li>
                </ul>
              </div>
            ) : null}
          </li>

          <li>
            <Link
              to="/contractors/"
              className={styles.mobileLink}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {t("menu.contractors")}
            </Link>
          </li>

          <li>
            <Link
              to="/portfolio"
              className={styles.mobileLink}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {t("menu.portfolio")}
            </Link>
          </li>

          <li>
            <Link
              to="/about/"
              className={styles.mobileLink}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {t("menu.about")}
            </Link>
          </li>

          <li>
            <Link
              to="/contact/"
              className={styles.mobileLink}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {t("menu.contact")}
            </Link>
          </li>

          <li>
            <Link
              to="/blog"
              className={styles.mobileLink}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {t("menu.blog")}
            </Link>
          </li>

          <li className="mt-2">
            <a
              href={ctaHref}
              target={ctaHref.startsWith("http") ? "_blank" : undefined}
              rel={ctaHref.startsWith("http") ? "noreferrer" : undefined}
              className={styles.mobileCta}
              onClick={() => {
                setIsMenuOpen(false);
                setServicesOpenMobile(false);
              }}
            >
              {ctaLabel}
            </a>
          </li>
        </ul>
      </div>

      {showBackToTop ? (
        <button
          onClick={scrollToTop}
          className={styles.backToTopButton}
          aria-label="Back to top"
        >
          <FaArrowUp size={20} />
        </button>
      ) : null}
    </nav>
  );
};

export default Navigation;

const styles = {
  container:
    "relative z-10 mx-0 sm:mx-8 px-4 py-2 rounded-none sm:rounded-full bg-transparent sm:bg-secondary",

  // Mobile
  burgerButton: "md:hidden block focus:outline-none mx-auto",
  mobilePanel:
    "md:hidden fixed left-0 top-0 w-full h-full bg-secondary pt-20 pb-10 px-6 overflow-y-auto",
  mobileLink:
    "text-white text-2xl px-4 py-0 hover:underline hover:text-purplelight text-nowrap",
  mobileAccordionButton:
    "w-full flex items-center justify-between px-4 py-3 rounded-xl border border-white/10 bg-white/5 text-white text-xl",
  mobileAccordionPanel: "mt-2 px-2",
  mobileSubLink:
    "block w-full px-4 py-2 rounded-lg text-white/90 hover:bg-white/10",
  mobileSubLinkMuted:
    "block w-full px-4 py-2 rounded-lg text-white/70 hover:bg-white/10",
  mobileCta:
    "inline-flex rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center",

  // Desktop
  desktopWrapper: "hidden md:flex items-center justify-between gap-6",
  desktopList: "flex items-center gap-2",
  item: "my-0",
  link: "text-white text-base px-3 py-2 hover:underline hover:text-purplelight text-nowrap",
  dropdownButton:
    "text-white text-base px-3 py-2 hover:underline hover:text-purplelight text-nowrap inline-flex items-center",
  dropdownPanel:
    "absolute left-0 mt-2 w-80 rounded-2xl border border-black/10 bg-white/80 p-3 shadow-lg supports-[backdrop-filter]:bg-white/50 supports-[backdrop-filter]:backdrop-blur",
  dropdownLink:
    "block w-full rounded-xl px-3 py-2 text-sm text-black/85 hover:bg-black/5",
  dropdownLinkMuted:
    "block w-full rounded-xl px-3 py-2 text-sm text-black/65 hover:bg-black/5",

  ctaButton:
    "hidden md:inline-flex rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center whitespace-nowrap",

  // Shared
  menuOpen: "block",
  menuClosed: "hidden",

  backToTopButton:
    "fixed bottom-4 right-4 bg-secondary text-white p-2 rounded-full shadow-lg z-50",
};
