import React from "react";
import i18next, { type Resource, type ResourceLanguage } from "i18next";
import { I18nextProvider } from "react-i18next";
import { I18nextContext } from "gatsby-plugin-react-i18next";

type LocaleNode = {
  ns?: string | null;
  data: Record<string, unknown> | string;
  language?: string | null;
};

export type I18nPageContext = {
  i18n?: {
    routed: boolean;
    language: string;
    languages: string[];
    originalPath: string;
    defaultLanguage: string;
    path: string;
    generateDefaultLanguagePage?: boolean;
    siteUrl?: string;
  };
};

export type LocaleQueryData = {
  locales?: {
    edges?: Array<{
      node: LocaleNode;
    }>;
  };
};

type Props = {
  data?: LocaleQueryData;
  pageContext?: I18nPageContext;
  children: React.ReactNode;
};

const I18N_OPTIONS = {
  interpolation: { escapeValue: false },
  nsSeparator: false as const,
};

const parseLocaleData = (input: LocaleNode["data"]): ResourceLanguage => {
  if (input && typeof input === "object") {
    return input as ResourceLanguage;
  }

  try {
    return JSON.parse(input) as ResourceLanguage;
  } catch {
    return {} as ResourceLanguage;
  }
};

export const I18nHeadProvider: React.FC<Props> = ({
  data,
  pageContext,
  children,
}) => {
  const context = pageContext?.i18n;
  const localeEdges = data?.locales?.edges ?? [];

  if (!context || localeEdges.length === 0) {
    return <>{children}</>;
  }

  const namespaces = localeEdges
    .map((edge) => edge.node?.ns)
    .filter(Boolean) as string[];
  const defaultNS = namespaces.find((ns) => ns !== "translation") || "translation";
  const fallbackNS = namespaces.filter((ns) => ns !== defaultNS);

  const resources = localeEdges.reduce<Resource>(
    (acc, edge) => {
      const node = edge.node;
      if (!node?.language) return acc;
      const parsedData = parseLocaleData(node.data);
      if (!acc[node.language]) acc[node.language] = {};
      acc[node.language]![node.ns || defaultNS] = parsedData;
      return acc;
    },
    {}
  );

  const i18n = i18next.createInstance();
  void i18n.init({
    ...I18N_OPTIONS,
    resources,
    lng: context.language,
    fallbackLng: context.defaultLanguage,
    defaultNS,
    fallbackNS,
    react: {
      useSuspense: false,
    },
    });

  if (i18n.language !== context.language) {
    i18n.changeLanguage(context.language);
  }

  return (
    <I18nextProvider i18n={i18n}>
      <I18nextContext.Provider
        value={{
          ...context,
          generateDefaultLanguagePage:
            context.generateDefaultLanguagePage ?? false,
          siteUrl: context.siteUrl ?? "",
        }}
      >
        {children}
      </I18nextContext.Provider>
    </I18nextProvider>
  );
};

export default I18nHeadProvider;
